S = "Hakeem Force Academy"
QS = [
(S, "The SUPARCO of Pakistan is an organisation that works in which field?", ["Agriculture", "Space and upper atmosphere research", "Nuclear power", "Water resources"], 1, "SUPARCO stands for Space and Upper Atmosphere Research Commission. It is Pakistan's national space agency.", "SUPARCO was founded in 1961 and launched Pakistan's first satellite Badr-1 in 1990.", [3244, 3438]),
(S, "Iqbal's famous 1930 speech at the annual session of the All India Muslim League is known as which address?", ["Lahore Address", "Allahabad Address", "Delhi Address", "Aligarh Address"], 1, "Allama Iqbal delivered his Presidential Address at Allahabad in December 1930. In it he proposed a separate Muslim state in north-west India.", "The Allahabad Address is considered the intellectual root of the Pakistan idea.", [4091]),
(S, "What is the last sermon of the Holy Prophet (SAW) called?", ["Khutbah Hajjat-ul-Wida", "Khutbah Tabuk", "Khutbah Ghadir", "Khutbah Fath"], 0, "The Prophet (SAW) delivered his final sermon during the Farewell Hajj at Arafat. It is called Khutbah Hajjat-ul-Wida.", "The Farewell Hajj took place in 10 AH.", [3689]),
(S, "A car runs at 60 km/hr and a train runs at twice the speed of the car. What is the speed of the train?", ["30 km/hr", "90 km/hr", "120 km/hr", "180 km/hr"], 2, "Train speed = 2 x 60 = 120 km/hr. Speed does not change with the time taken, so it is still 120 km/hr after 30 minutes.", "In 30 minutes this train would cover 60 km.", [2366]),
(S, "Ahsan Ramzan, who became the youngest world champion in 2022, is a player of which sport?", ["Squash", "Hockey", "Snooker", "Cricket"], 2, "Ahsan Ramzan of Lahore won the IBSF World Snooker Championship in Doha in 2022 at the age of 16. He became the youngest ever winner.", "He beat Iran's Amir Sarkosh in that final.", [761]),
(S, "Tiananmen Square is situated in which city?", ["Shanghai", "Tokyo", "Beijing", "Seoul"], 2, "Tiananmen Square lies in the centre of Beijing, the capital of China. It is named after the Gate of Heavenly Peace.", "It is one of the largest public squares in the world.", [4386, 1572]),
(S, "What is the antonym of 'stagnant'?", ["Still", "Flowing", "Motionless", "Stale"], 1, "Stagnant means not flowing or moving, as in stagnant water. Its opposite is flowing.", "Stagnant can also describe an economy that is not growing.", [278, 3869]),
(S, "In which year was the first postage stamp of Pakistan issued?", ["1947", "1948", "1950", "1952"], 1, "Pakistan issued its first postage stamps on 9 July 1948. They were a set of four stamps showing the Pakistani flag and national symbols.", "Before that, Indian stamps overprinted with the word Pakistan were used in 1947.", [1248]),
(S, "In football, what did BPL originally stand for in the English league?", ["Barclays Premier League", "British Premier League", "Big Premier League", "Best Players League"], 0, "The English top division was sponsored by Barclays from 2001 to 2016 and was called the Barclays Premier League (BPL). Today it is simply the Premier League.", "BPL also stands for the Bangladesh Premier League in cricket.", [217]),
(S, "What does OPAC stand for in library science?", ["Online Public Access Catalogue", "Open Public Archive Centre", "Official Printed Access Card", "Online Publishing and Cataloguing"], 0, "OPAC means Online Public Access Catalogue. It is a computerised database that lets users search a library's holdings.", "It replaced the traditional card catalogue.", [3233]),
(S, "The Sun is currently in which stage of a star's life?", ["Red giant", "Main sequence", "White dwarf", "Supernova"], 1, "The Sun fuses hydrogen into helium in its core, which is the main sequence stage. It has been in this stage for about 4.6 billion years.", "In about 5 billion years the Sun will become a red giant.", [539]),
(S, "Fill in the blank: She arrived ___ the station.", ["in", "on", "at", "to"], 2, "We use the preposition at with a specific point or place such as a station. So the sentence is: She arrived at the station.", "We use arrive in for large places such as cities and countries.", [1960]),
(S, "In which city was the first television station of Pakistan set up?", ["Karachi", "Islamabad", "Lahore", "Rawalpindi"], 2, "Pakistan Television started its first broadcast from Lahore on 26 November 1964. It was a pilot station.", "Karachi and Dhaka stations followed in 1966.", [917]),
(S, "Which is the largest railway station of Pakistan, according to most sources?", ["Karachi Cantonment", "Lahore Junction", "Peshawar Cantonment", "Quetta"], 1, "Lahore Junction is most commonly named as the largest railway station of Pakistan by area.", "Sources differ on this point, and Karachi Cantonment and Rohri are also described as very large.", [4375, 1322]),
(S, "After which battle did the Quraysh stop their attacks on Madina, as the Prophet (SAW) said they would no longer attack?", ["Badr", "Uhud", "Khandaq", "Hunain"], 2, "After the failed siege of Madina in the Battle of Khandaq (Ahzab) in 5 AH, the Prophet (SAW) said that the Quraysh would not attack again and the Muslims would march against them.", "The Battle of Khandaq was won mainly by the trench dug on the advice of Salman Farsi (RA).", [1716]),
(S, "Marvi, the famous folk tale, belongs to which province of Pakistan?", ["Punjab", "Balochistan", "Khyber Pakhtunkhwa", "Sindh"], 3, "Umar Marvi is one of the seven famous folk heroines of Shah Abdul Latif Bhittai's Sindhi poetry. The story belongs to Sindh.", "Marvi was a village girl of Tharparkar who refused the offers of the ruler Umar Soomro.", [2836, 2837]),
(S, "The graphical representation of which type of equation is a straight line?", ["Quadratic equation", "Linear equation", "Cubic equation", "Exponential equation"], 1, "A linear equation such as y = mx + c has degree one in its variables. Its graph is always a straight line.", "A quadratic equation gives a parabola.", [3028]),
(S, "Which word is closest in meaning to 'strange'?", ["Common", "Odd", "Familiar", "Normal"], 1, "Strange means unusual or unexpected, and odd has the same meaning. The other options mean the opposite.", "Other synonyms of strange are peculiar and queer.", [3336]),
(S, "How many Muslim soldiers marched in the army for the Ghazwa of Tabuk?", ["300", "3,000", "10,000", "30,000"], 3, "The Prophet (SAW) led about 30,000 Muslim fighters to Tabuk in 9 AH. It was the largest Muslim army up to that time.", "The campaign is also called the Army of Hardship (Jaish-ul-Usrah).", [4173]),
(S, "What is the closest meaning of 'strenuous'?", ["Easy", "Arduous", "Pleasant", "Brief"], 1, "Strenuous means needing great effort or energy. Arduous has the same meaning.", "The opposite of strenuous is effortless or easy.", [3549, 3780, 3988]),
(S, "What is the central subject of the Holy Quran?", ["Trade", "Mankind and its guidance", "Astronomy", "History of kings"], 1, "The Quran is a book of guidance addressed to mankind. Its main subject is man and his success in this world and the Hereafter.", "The Quran has 114 surahs and 30 paras.", [3955]),
(S, "What is a synonym of 'subversion'?", ["Loyalty", "Support", "Undermining", "Repair"], 2, "Subversion means an attempt to weaken or overthrow an established authority from within. Undermining carries the same sense.", "Sabotage is another close synonym.", [3337]),
(S, "What is the antonym of 'subversion'?", ["Rebellion", "Sabotage", "Treachery", "Support"], 3, "Subversion means weakening an authority, so its opposite is supporting or upholding it. Support is the best opposite among the options.", "Subversion usually refers to secret acts against a government.", [1090]),
(S, "The Suez Canal separates Africa from which continent?", ["Europe", "Asia", "Australia", "South America"], 1, "The Suez Canal in Egypt separates the African mainland from the Sinai Peninsula, which is part of Asia. It also joins the Mediterranean Sea to the Red Sea.", "The canal was opened in 1869.", [266, 561]),
(S, "Which prophet is famous in Islamic tradition for suffering the longest illness with patience?", ["Hazrat Ayub (AS)", "Hazrat Yunus (AS)", "Hazrat Musa (AS)", "Hazrat Isa (AS)"], 0, "Hazrat Ayub (AS) suffered a long illness and loss of wealth and remained patient. He is the symbol of sabr.", "The Quran mentions his prayer in Surah Al-Anbiya and Surah Sad.", [4851]),
(S, "After which event did Hazrat Abu Sufyan (RA) accept Islam?", ["Battle of Badr", "Treaty of Hudaybiyyah", "Conquest of Makkah", "Battle of Uhud"], 2, "Abu Sufyan accepted Islam at the time of the Conquest of Makkah in Ramadan 8 AH.", "Before this he had led the Quraysh in several battles against the Muslims.", [1710, 4196]),
(S, "In which Hijri year did Abu Sufyan accept Islam?", ["2 AH", "6 AH", "8 AH", "10 AH"], 2, "Abu Sufyan embraced Islam on the occasion of the Conquest of Makkah, which took place in 8 AH.", "Some candidates remember 6 AH, but the Conquest of Makkah was in 8 AH.", [953]),
(S, "Sukkur city is located in which province of Pakistan?", ["Punjab", "Balochistan", "Sindh", "Khyber Pakhtunkhwa"], 2, "Sukkur is a city on the bank of the River Indus in the province of Sindh.", "The Sukkur Barrage was completed in 1932.", [536]),
]
